/**
 * Regenerates src/export/logoData.js from src/assets/images/app-logo.png.
 * The PDF embeds the logo as a data URI (no file access, no loading delay).
 * Run after changing the logo:  node scripts/make-logo-data.js
 */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const png = fs.readFileSync(path.join(root, 'src/assets/images/app-logo.png'));
const out = `/**
 * GENERATED by scripts/make-logo-data.js from src/assets/images/app-logo.png
 * — do not edit by hand. The app logo as a data URI for the PDF header.
 */
export const APP_LOGO_DATA_URI =
  'data:image/png;base64,${png.toString('base64')}';
`;
fs.writeFileSync(path.join(root, 'src/export/logoData.js'), out);
console.log(`logoData.js written (${png.length} bytes png)`);
